def double_result(f):
    def wrapper(n):
        return f(n) * 2
    return wrapper
@double_result
def val(n):
    return n + 1
print(val(5), val(0))

def addn(k):
    def deco(f):
        def w(x):
            return f(x) + k
        return w
    return deco
@addn(10)
def inc(x):
    return x * 1
print(inc(5))

